# Let's check the type and structure of search results
sections = ["[grade]", "[grader tail]", "[facts]", "[first wrong step]", "[checkpoint]", "[request]"]
for s in sections:
    results = await CONTEXT.search(s)
    print(f"=== {s}: type={type(results)} ===")
    print(f"  results: {results}")
    # Try to iterate
    if hasattr(results, '__iter__'):
        for i, r in enumerate(results):
            print(f"    [{i}]: offset={r['offset']}, snippet={r['snippet'][:200]}")
            if i >= 3:
                break
    print()
